#ifndef MSDOS_BOOTDISK_DATA_H
#define MSDOS_BOOTDISK_DATA_H

#include <stdint.h>

typedef struct {
    uint32_t offset;
    uint32_t len;
    const unsigned char *data;
} msdos_bootdisk_run;

typedef struct {
    int size_kb;                    /* 360, 720, 1440 */
    uint32_t bytes;
    uint32_t config_offset;         /* CONFIG.SYS, fixed size, rewritten in place */
    uint32_t config_size;
    const msdos_bootdisk_run *runs; /* the non-zero sectors */
    int nruns;
} msdos_bootdisk_image;

extern const msdos_bootdisk_image msdos_bootdisk_images[];
extern const int msdos_bootdisk_image_count;
extern const char msdos_bootdisk_contents[];

#endif
